-- pintopets_horse_cares: tenant-scoped rows behind /horse-cares (generated by `opsapi make:resource`).
-- Runs once, inside a transaction. Never edit it after it has been applied —
-- add a new migration file instead.
return function(schema, db)
    db.query([[
        CREATE TABLE IF NOT EXISTS pintopets_horse_cares (
            id BIGSERIAL PRIMARY KEY,
            uuid UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
            namespace_id INTEGER NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
            pet_uuid UUID NOT NULL REFERENCES pintopets_pets(uuid) ON DELETE CASCADE,
            created_by_user_uuid UUID NOT NULL,
            kind VARCHAR(255) NOT NULL,
            done_on DATE NOT NULL,
            provider VARCHAR(255),
            result VARCHAR(255),
            next_due_on DATE,
            notes TEXT,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            CONSTRAINT pintopets_horse_cares_kind_check CHECK (kind IN ('farrier', 'dental', 'worm_egg_count'))
        )
    ]])
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_horse_cares_namespace ON pintopets_horse_cares (namespace_id, id DESC)")
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_horse_cares_pet ON pintopets_horse_cares (namespace_id, pet_uuid)")
end
